def solve(num: int) -> str:
    if num == 0:
        return "Zero"
    return "Even" if num % 2 == 0 else "Odd"

def solve(n: int) -> int:
    sign = -1 if n < 0 else 1
    s = str(abs(n))[::-1]
    return sign * int(s)

def solve(s: str) -> tuple:
    vowels = set("aeiou")
    v_cnt = sum(1 for c in s.lower() if c in vowels)
    c_cnt = sum(1 for c in s.lower() if c.isalpha() and c not in vowels)
    return (v_cnt, c_cnt)

def solve(n: int) -> int:
    ans = 1
    for i in range(1, n + 1):
        ans *= i
    return ans

def solve(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def solve(n: int) -> int:
    if n <= 1: return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def solve(n: int) -> bool:
    if n <= 1: return False
    if n <= 3: return True
    if n % 2 == 0 or n % 3 == 0: return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def solve(n: int) -> int:
    cnt = 0
    while n:
        n &= (n - 1)
        cnt += 1
    return cnt

def solve(a: int, b: int) -> tuple:
    a, b = b, a
    return (a, b)

def solve(nums: list) -> dict:
    from collections import Counter
    return dict(Counter(nums))

def solve(a: list, b: list) -> list:
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            res.append(a[i])
            i += 1
        else:
            res.append(b[j])
            j += 1
    res.extend(a[i:])
    res.extend(b[j:])
    return res

def solve(words: list) -> list:
    from collections import defaultdict
    groups = defaultdict(list)
    for w in words:
        groups["".join(sorted(w))].append(w)
    return sorted([sorted(g) for g in groups.values()])

def solve(items: list) -> list:
    seen = set()
    res = []
    for x in items:
        if x not in seen:
            seen.add(x)
            res.append(x)
    return res

def solve(n: int) -> int:
    memo = {}
    def fib(k):
        if k <= 1: return k
        if k not in memo:
            memo[k] = fib(k - 1) + fib(k - 2)
        return memo[k]
    return fib(n)

def solve(start: int, stop: int, step: int) -> list:
    def gen(a, b, c):
        curr = a
        while curr < b:
            yield curr
            curr += c
    return list(gen(start, stop, step))

def solve(a: int, b: int) -> str:
    try:
        return f"{a / b:.2f}"
    except ZeroDivisionError:
        return "Error: Division by zero"

